        "授课教师原文未写，每周几节原文未写。初中：初一口风琴（乐理＋合奏校歌）→初二陶艺彩泥（主题创作＋作品展）→初三合唱（和声基础＋年级合唱比赛）。高中：高一音乐素养（音乐史与鉴赏）→高二漫画（主题创作＋漫画展）→高三指挥（手势与节奏、指挥合唱展示）。出口：每年艺术节覆盖各年级课程成果，开闭幕式设才艺展示与作品展览。"
